select case when duration_sec >= 492 then 'high' when duration_sec >= 165 then 'mid' else 'low' end as duration_sec_bucket, max(duration_sec) as max_duration_sec, count(*) as num_web_events from web_events where event_time >= '2023-12-23' and page in ('/search', '/cart') group by duration_sec_bucket having sum(case when event_type = 'page_view' then 1 else 0 end) > 72 order by max_duration_sec
